def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements Dijkstra's algorithm to find the shortest path in a weighted directed graph represented as an adjacency list.
    Returns the shortest distance and the corresponding path from start to end.
    """
    min_heap = [(0, start)]
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}

    while min_heap:
        current_distance, current_node = heapq.heappop(min_heap)

